#include "trellis35_test_support.h"

#include <bit>

namespace {

// Frozen before executing the WP13 oracle. The warp FWHT changes FP32
// association relative to the direct 128-FMA reference but does not change the
// mathematical transform.
constexpr float kWp13H128AbsoluteTolerance = 2.0e-5F;
constexpr float kWp13H128RelativeTolerance = 2.0e-5F;

void TestH128WarpExhaustiveOracle() {
  constexpr std::uint64_t kVectors = 130U;
  constexpr std::uint64_t kElements = kVectors * 128U;
  DeviceBuffer<float> input(kElements);
  DeviceBuffer<float> output(kElements);
  std::vector<float> host_input(kElements, 0.0F);
  for (unsigned impulse = 0U; impulse < 128U; ++impulse) {
    host_input[static_cast<std::uint64_t>(impulse) * 128U + impulse] = 1.0F;
  }
  for (unsigned index = 0U; index < 128U; ++index) {
    host_input[128U * 128U + index] =
        std::sin(static_cast<float>(index * 37U + 5U) * 0.03125F);
    host_input[129U * 128U + index] =
        std::cos(static_cast<float>(index * 19U + 11U) * 0.015625F) *
        static_cast<float>(static_cast<int>(index % 7U) - 3);
  }
  CHECK(Upload(input, host_input, "upload exhaustive H128 oracle input"));
  const auto status = gem16::internal::LaunchTrellis35H128WarpDiagnostic(
      input.get(), output.get(), kVectors, nullptr);
  CHECK(status.ok());
  CHECK(CudaOk(cudaDeviceSynchronize(), "synchronize H128 warp oracle"));
  std::vector<float> actual(kElements);
  CHECK(CudaOk(cudaMemcpy(actual.data(), output.get(), output.bytes(),
                          cudaMemcpyDeviceToHost),
               "download H128 warp oracle"));
  std::vector<float> expected(kElements, 0.0F);
  constexpr float kNormalization = 0.08838834764831845F;
  for (std::uint64_t vector = 0U; vector < kVectors; ++vector) {
    for (unsigned column = 0U; column < 128U; ++column) {
      float accumulator = 0.0F;
      for (unsigned row = 0U; row < 128U; ++row) {
        const float sign = (std::popcount(row & column) & 1U) == 0U
                               ? 1.0F
                               : -1.0F;
        accumulator = std::fma(host_input[vector * 128U + row], sign,
                               accumulator);
      }
      expected[vector * 128U + column] = accumulator * kNormalization;
    }
  }
  Compare(expected, actual, kWp13H128AbsoluteTolerance,
          kWp13H128RelativeTolerance, "WP13 exhaustive H128 warp oracle");

  DeviceBuffer<float> roundtrip(kElements);
  const auto inverse_status =
      gem16::internal::LaunchTrellis35H128WarpDiagnostic(
          output.get(), roundtrip.get(), kVectors, nullptr);
  CHECK(inverse_status.ok());
  CHECK(CudaOk(cudaDeviceSynchronize(), "synchronize H128 warp roundtrip"));
  std::vector<float> reconstructed(kElements);
  CHECK(CudaOk(cudaMemcpy(reconstructed.data(), roundtrip.get(),
                          roundtrip.bytes(), cudaMemcpyDeviceToHost),
               "download H128 warp roundtrip"));
  Compare(host_input, reconstructed, kWp13H128AbsoluteTolerance,
          kWp13H128RelativeTolerance, "WP13 H128 warp roundtrip");
}

void TestTransformsAndDownPadding() {
  constexpr std::uint64_t kLogical =
      gem16::internal::kTrellis35ExpertIntermediate;
  constexpr std::uint64_t kPhysical = gem16::internal::kTrellis35DownInput;
  DeviceBuffer<float> input(kLogical);
  DeviceBuffer<std::uint16_t> sidecar(kPhysical);
  DeviceBuffer<float> transformed(kPhysical);
  DeviceBuffer<float> reconstructed(kPhysical);
  std::vector<float> host_input(kLogical);
  std::vector<std::uint16_t> host_sidecar(kPhysical, 0x3c00U);
  for (std::uint64_t index = 0U; index < kLogical; ++index) {
    host_input[index] =
        std::sin(static_cast<float>(index * 29U + 3U) * 0.015625F);
  }
  if (!Upload(input, host_input, "upload transform input") ||
      !Upload(sidecar, host_sidecar, "upload transform sidecar")) {
    return;
  }
  auto status = gem16::internal::LaunchTrellis35InputTransformM1(
      input.get(), sidecar.get(), transformed.get(), kLogical, kPhysical,
      nullptr);
  CHECK(status.ok());
  const auto output_status = gem16::internal::LaunchTrellis35OutputTransformM1(
      transformed.get(), sidecar.get(), reconstructed.get(), kPhysical,
      nullptr);
  CHECK(output_status.ok());
  CHECK(CudaOk(cudaDeviceSynchronize(), "synchronize transform round trip"));
  std::vector<float> host_reconstructed(kPhysical);
  CHECK(CudaOk(cudaMemcpy(host_reconstructed.data(), reconstructed.get(),
                          reconstructed.bytes(), cudaMemcpyDeviceToHost),
               "download transform reconstruction"));
  float maximum_logical_error = 0.0F;
  float maximum_padding = 0.0F;
  for (std::uint64_t index = 0U; index < kLogical; ++index) {
    maximum_logical_error = std::max(
        maximum_logical_error,
        std::fabs(host_reconstructed[index] - host_input[index]));
  }
  for (std::uint64_t index = kLogical; index < kPhysical; ++index) {
    maximum_padding =
        std::max(maximum_padding, std::fabs(host_reconstructed[index]));
  }
  std::cout << "Down 704->768 transform roundtrip max_abs="
            << maximum_logical_error << " padding_max_abs=" << maximum_padding
            << '\n';
  CHECK(maximum_logical_error <= 2.0e-6F);
  CHECK(maximum_padding <= 2.0e-6F);

  constexpr std::uint64_t kFused = gem16::internal::kTrellis35GateUpOutput;
  DeviceBuffer<float> fused_transformed(kFused);
  DeviceBuffer<std::uint16_t> fused_sidecar(kFused);
  DeviceBuffer<float> fused_output(kFused);
  std::vector<float> host_fused(kFused, 0.0F);
  std::vector<std::uint16_t> host_fused_sidecar(kFused, 0x3c00U);
  // Index 750 shares the [640, 768) Hadamard block with both the final Gate
  // values [640, 704) and the first Up values [704, 768).
  host_fused[750] = 1.0F;
  if (!Upload(fused_transformed, host_fused, "upload fused impulse") ||
      !Upload(fused_sidecar, host_fused_sidecar,
              "upload fused output sidecar")) {
    return;
  }
  const auto fused_status = gem16::internal::LaunchTrellis35OutputTransformM1(
      fused_transformed.get(), fused_sidecar.get(), fused_output.get(),
      kFused, nullptr);
  CHECK(fused_status.ok());
  CHECK(CudaOk(cudaDeviceSynchronize(), "synchronize fused output transform"));
  std::vector<float> host_fused_output(kFused);
  CHECK(CudaOk(cudaMemcpy(host_fused_output.data(), fused_output.get(),
                          fused_output.bytes(), cudaMemcpyDeviceToHost),
               "download fused output transform"));
  float gate_energy = 0.0F;
  float up_energy = 0.0F;
  for (std::uint64_t index = 640U; index < 704U; ++index) {
    gate_energy += std::fabs(host_fused_output[index]);
  }
  for (std::uint64_t index = 704U; index < 768U; ++index) {
    up_energy += std::fabs(host_fused_output[index]);
  }
  std::cout << "fused Gate+Up crossing-block gate_l1=" << gate_energy
            << " up_l1=" << up_energy << '\n';
  CHECK(gate_energy > 0.0F && up_energy > 0.0F);
}


void TestGateInputFusionExact() {
  using namespace gem16::internal;
  FamilyStorage family(kTrellis35GateUpInput, kTrellis35GateUpOutput, 311U);
  for (const unsigned assignments : {8U, 24U}) {
    DeviceBuffer<float> input((assignments / 8U) * kTrellis35GateUpInput);
    DeviceBuffer<std::uint32_t> ids(assignments);
    DeviceBuffer<float> reference_transform(assignments * kTrellis35GateUpInput);
    DeviceBuffer<float> fused_transform(reference_transform.elements());
    DeviceBuffer<std::uint8_t> reference_fp8(reference_transform.elements());
    DeviceBuffer<std::uint8_t> fused_fp8(reference_transform.elements());
    DeviceBuffer<float> reference_scale(assignments), fused_scale(assignments);
    std::vector<std::uint32_t> host_ids(assignments);
    for (unsigned i = 0U; i < assignments; ++i) host_ids[i] = (i * 17U) % 128U;
    CHECK(Upload(ids, host_ids, "upload fusion IDs"));
    for (const float amplitude : {0.0F, 1.0e-5F, 3.0F, 1.0e5F}) {
      std::vector<float> host_input(input.elements());
      for (std::size_t i = 0U; i < host_input.size(); ++i) {
        host_input[i] = std::sin(static_cast<float>(i) * 0.013F) * amplitude;
      }
      CHECK(Upload(input, host_input, "upload fusion input"));
      CHECK(LaunchTrellis35GateInputTransformQuantize(
          input.get(), family.binding.suh_f16, ids.get(), reference_fp8.get(),
          reference_scale.get(), assignments, false, reference_transform.get(), nullptr).ok());
      CHECK(LaunchTrellis35GateInputTransformQuantize(
          input.get(), family.binding.suh_f16, ids.get(), fused_fp8.get(),
          fused_scale.get(), assignments, true, fused_transform.get(), nullptr).ok());
      CHECK(CudaOk(cudaDeviceSynchronize(), "synchronize GateUp fusion"));
      auto exact = [](const auto& a, const auto& b) {
        std::vector<std::byte> x(a.bytes()), y(b.bytes());
        CHECK(CudaOk(cudaMemcpy(x.data(), a.get(), a.bytes(), cudaMemcpyDeviceToHost), "copy reference fusion bytes"));
        CHECK(CudaOk(cudaMemcpy(y.data(), b.get(), b.bytes(), cudaMemcpyDeviceToHost), "copy fused bytes"));
        CHECK(x == y);
      };
      exact(reference_transform, fused_transform);
      exact(reference_fp8, fused_fp8);
      exact(reference_scale, fused_scale);
      // Qualify the production specialization that omits diagnostic FP32 stores.
      CHECK(LaunchTrellis35GateInputTransformQuantize(
          input.get(), family.binding.suh_f16, ids.get(), fused_fp8.get(),
          fused_scale.get(), assignments, true, nullptr, nullptr).ok());
      CHECK(CudaOk(cudaDeviceSynchronize(), "synchronize production GateUp fusion"));
      exact(reference_fp8, fused_fp8);
      exact(reference_scale, fused_scale);
    }
  }
}

}  // namespace

int RunTrellis35TransformTests() {
  TestH128WarpExhaustiveOracle();
  TestTransformsAndDownPadding();
  TestGateInputFusionExact();
  return failures;
}

